// The Ad Studio's option banks: the campaign brief vocabulary, the product
// facts the AI is allowed to claim, the canvas sizes, and the creative
// templates.
//
// These used to live inside initStudio() in studio-core.ts, which meant the
// only way to read them was to run the vanilla studio. They are plain data, so
// they live here instead and both the existing core and anything built later
// import the same copy. Moving them changes no behaviour.
//
// Claims rule: PRODUCTS[x].facts is the ONLY thing the AI may assert about a
// product. Adding a claim here lets it into paid ads, so it must already be
// true on the published page.

export interface AngleBank { name: string; visual: string }
export interface AudienceBank { name: string; note: string }
export interface FormatBank {
  name: string; ratio: string; spec: string; label: string;
  /** True Meta pixels. adDimensions() renders and exports at exactly this. */
  w: number; h: number;
}
export interface ProductBank {
  name: string; tag: string; facts: string; url: string; campaign: string;
  angles: string[];
  ctas: Record<string, string>;
  headlines: string[];
  descs: string[];
  primaries: Record<string, string[]>;
  /** Audience-tuned primaries, merged in from the AI pack below. */
  audiencePrimaries?: Record<string, string[]>;
}

